    host: '127.0.0.1',
    port: '8108',
    protocol: 'http'
  }],
  apiKey: typesenseApiKey,
  connectionTimeoutSeconds: 5
});

async function main() {
  try {
    const res = await client.analytics.rules('test_rule').delete();
